"""Draw actual selected repository paths as a native, non-card SVG tree."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];H=R/'presentation'
groups=[('data',['raw','external','processed']),('src',['strength','strength_joint','regions']),('outputs',['tables','figures','logs']),('scripts',['analyze_confirmed_eras.py','analyze_history_window.py','build_submission_package.py']),('研究',['01_年代变化','05_赛前实力','08_未来比赛预测']),('文档',['01_项目方案','02_环境配置','05_团队协作']),('paper',['final_paper.pdf','figures','language_revision_20261107']),('presentation',['index.html','assets','results_template.csv'])]
data=[]
for i,(name,leaves) in enumerate(groups):
 assert (R/name).is_dir()
 for leaf in leaves:assert (R/name/leaf).exists(),(name,leaf)
 data.append({'name':name+'/','path':name,'leaves':[{'name':n+('/' if (R/name/n).is_dir() else ''),'path':name+'/'+n} for n in leaves]})
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Football research — repository tree</title><style>
*{box-sizing:border-box}body{margin:0;background:#07162c;color:#eef6ff;font:17px 'Segoe UI',Arial,sans-serif;overflow:hidden}header{height:75px;padding:15px 3vw;display:flex;align-items:center;justify-content:space-between}h1{font-size:22px;margin:0 0 5px}small{font-size:13px;color:#a9c0d6}button{background:#132e4a;color:white;border:1px solid #426483;border-radius:7px;padding:8px 13px;cursor:pointer;font:inherit}button:hover{background:#275278}svg{width:100vw;height:calc(100vh - 110px);background:radial-gradient(ellipse at 50% 50%,#19375799,transparent 52%)}svg text{font-family:'Segoe UI',Arial,sans-serif;fill:#ecf6ff}.branch{cursor:pointer;outline:none}.branch:hover .directory,.branch:focus .directory{fill:#fff}.branch:hover .mainwire,.branch:focus .mainwire{stroke-width:5}.mainwire{stroke-width:2.5;fill:none;opacity:.85;stroke-dasharray:700;animation:draw 1.1s both}.twig{fill:none;stroke-width:1.4;opacity:.7}.leaf text{font-size:16px}.leaf:hover text{fill:#fff;text-decoration:underline}.leaf{cursor:pointer}footer{height:35px;display:flex;justify-content:space-between;padding:0 3vw;color:#b0c4d7;font-size:13px}#selection{max-width:60vw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@keyframes draw{from{stroke-dashoffset:700}to{stroke-dashoffset:0}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}@media(max-height:650px){header{height:60px}svg{height:calc(100vh - 95px)}}
</style><header><div><h1>python-football-project</h1><small>REAL DIRECTORY STRUCTURE · Selected paths, not an exhaustive listing</small></div><div><button id="show">Expand all</button> <button id="hide">Collapse all</button></div></header><svg viewBox="0 0 1600 800" role="img" aria-label="Repository directory tree"><defs><filter id="glow"><feGaussianBlur stdDeviation="4"/></filter></defs><g id="tree"></g></svg><footer><span id="selection">Select a folder to collapse or expand its children.</span><span>Containment lines · not runtime calls</span></footer><script>
const groups=__NODES__,colors=['#43c4ff','#7b92ff','#4be2bd','#e9af59','#d48aff','#fb9292','#77c9ed','#c3e278'];let expanded=groups.map(()=>true);const root={x:800,y:385};
function folder(x,y,c,size=1){return `<g transform="translate(${x} ${y}) scale(${size})"><path d="M0 4Q0 1 3 1H12L16 5H29Q32 5 32 8V23Q32 26 29 26H3Q0 26 0 23Z" fill="${c}"/><path d="M1 10H31" stroke="#ffffff55"/></g>`}
function render(){let s=`<circle cx="800" cy="385" r="100" stroke="#31597d" fill="#0e2742"/><circle cx="800" cy="385" r="118" stroke="#274561" fill="none" stroke-dasharray="3 12"/>${folder(766,341,'#e9b963',2.1)}<text x="800" y="427" text-anchor="middle" font-size="25" font-weight="700">REPOSITORY</text><text x="800" y="458" text-anchor="middle" font-size="15" fill="#bed4eb">8 folders · 24 selected entries</text>`;
groups.forEach((g,i)=>{let left=i<4,k=i%4,y=95+k*195,px=left?445:1080,rx=left?690:910,c=colors[i],ex=left?250:1310,cx=left?315:1255;let starty=385+(y-385)*.25;let d=`M${rx} ${starty} C${left?600:1000} ${starty},${left?610:990} ${y},${px} ${y}`;
s+=`<g class="branch" tabindex="0" role="button" aria-label="${g.name} toggle children" aria-expanded="${expanded[i]}" data-index="${i}"><path class="mainwire" d="${d}" stroke="${c}"/><circle cx="${px}" cy="${y}" r="6" fill="${c}"/>${folder(left?px-26:px+12,y-48,c,.8)}<text class="directory" x="${left?px-38:px+48}" y="${y-65}" text-anchor="${left?'end':'start'}" font-size="26" font-weight="700">${g.name}</text>`;
if(expanded[i])g.leaves.forEach((l,j)=>{let ly=y+(j-1)*43,from=left?px-13:px+15,to=left?ex+20:ex-12,label=l.name.length>23?l.name.slice(0,21)+'…':l.name;s+=`<g class="leaf" data-path="${l.path}"><title>${l.path}</title><path class="twig" d="M${from} ${y} C${cx} ${y},${cx} ${ly},${to} ${ly}" stroke="${c}"/><circle cx="${to}" cy="${ly}" r="3" fill="${c}"/><text x="${left?to-12:to+12}" y="${ly+5}" text-anchor="${left?'end':'start'}">${label}</text></g>`});s+='</g>'});document.querySelector('#tree').innerHTML=s;
document.querySelectorAll('.branch').forEach(g=>{let action=e=>{if(e.target.closest('.leaf')){document.querySelector('#selection').textContent=e.target.closest('.leaf').dataset.path;return}let i=+g.dataset.index;expanded[i]=!expanded[i];document.querySelector('#selection').textContent=groups[i].path+'/';render()};g.onclick=action;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action(e)}}})}
document.querySelector('#show').onclick=()=>{expanded.fill(true);render()};document.querySelector('#hide').onclick=()=>{expanded.fill(false);render()};render();window.repositoryTree={groups,expandAll:()=>document.querySelector('#show').click()};
</script></html>'''.replace('__NODES__',json.dumps(data,ensure_ascii=False))
(H/'repository_architecture.html').write_text(html,encoding='utf-8')
(H/'repository_visual_manifest.json').write_text(json.dumps({'decision_log_id':'R20261110-03','renderer':'presentation/make_repository_visual.py','scope':'Actual selected local directories; containment only','nodes':data,'output_sha256':hashlib.sha256((H/'repository_architecture.html').read_bytes()).hexdigest(),'archify_previous_output':'archive/archify_legacy/repository_architecture_archify_legacy.html','new_diagram_is_archify_generated':False},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Drew 8 actual folders and 24 verified paths without text cards.')
if __name__=='__main__':pass
